        move    y1,b                            ; the peak (x1 keeps the level's target)
        move    (r5)+n5                         ; r5 = kgov ($4b)
        move    x:(r5),x0
        move    x0,a
        move    #>41943,y1
        mac     x0,y1,a                         ; x 1.005
        move    #>1179647,y1
