        tfr     a,b
        add     x1,a
        add     a,b
        move    b,x:(r1)+
        move    x:(r1),x1
        sub     x1,a
        move    x:(r5)+,y1
        move    a,x0
        mpy     x0,y1,a
        tfr     a,b
        add     x1,a
        add     a,b
        move    b,x:(r1)+
        move    x:(r1),x1
        sub     x1,a
        move    x:(r5)+,y1
        move    a,x0
        mpy     x0,y1,a
        tfr     a,b
        add     x1,a
        add     a,b
        move    b,x:(r1)+
