; ---- the VCA input's high-pass ------------------------------------------------------------------------------
        move    x:(r1),x1                       ; (fills the add's wait)
        move    a,y0
        sub     x1,a
        move    x:(r5)+,y1
        move    a,x0
        mpy     x0,y1,a
        tfr     a,b
        add     x1,a
        add     a,b
        move    b,x:(r1)+
        move    y0,b
        sub     a,b                             ; v
; ---- the VCA: gain += step (48 bits), y = v gain << 3 ----------------------------------------------------------
        move    x:(r2)+,a                       ; (fills the sub's wait)
        move    b,x0
        move    x:(r2)+,a0
        move    x:(r2)+,b
        move    x:(r2)-,b0
        add     b,a
        move    (r2)-
        move    a0,y1                           ; (x0 holds v)
        move    y1,x:(r2)-
        move    a1,x:(r2)
        move    a1,y1
        mpy     x0,y1,a
        asl     #3,a,a
; ---- the BA662's ceiling: ONE signed table (in Y), step 2^14 (B3, the audit's T35): T = -KNEG[96..1], then KPOS[0..96]
;      and KPOS[96] again (194 words).  y within -LIM..LIM, u = y + LIM; the curve = T0 + f (T1 - T0), T0 = T[u >> 14],
;      T1 the next, f = u's 14 low bits.  A negative y reads the reflected interval, which gives the same sum to the bit;
;      the sign is in the table, no branch.  The clamp compares all 56 bits (a0 as the VCA left it): only a1 is read after.
        move    #$18,x0                         ; LIM = 96 x 2^14 (gen_module asserts it; the short form: bits 23..16)
        cmp     x0,a
        tgt     x0,a                            ; y above the table's end: the end
        move    #$e8,x0                         ; -LIM
        cmp     x0,a
        tlt     x0,a
        sub     x0,a                            ; u = y + LIM
        move    n3,r5                           ; the table's base (fills the sub's wait)
        move    a,y0
        asr     #14,a,a
        move    y0,b
        move    a1,n5
        and     #>$3fff,b
        asl     #9,b,b
        move    (r5)+n5
        move    b,x0                            ; the fraction, 23 bits
        move    y:(r5)+,y0                      ; T0
        move    y:(r5),y1                       ; T1
        move    y0,a
        mac     x0,y1,a
        mac     -y0,x0,a                        ; T0 + f (T1 - T0), exactly
; ---- MUFF: low = y's one-pole at 150 Hz, h = y - low (24 bits each), limited to the mode's +-L, then h - h f^2 with
;      f = (h K) << 4 (SOFT: the cubic soft clip, L = sqrt 2 Sm, saturating at 314,572; HARD: L = 314,572, K = 0; OFF:
;      no limit, K = 0, y as it came); y = low + h
        move    x:(r4)+,y1                      ; Gm
        move    x:(r4),x1 a,y0                  ; sm; y
        sub     x1,a
        move    a,x0
        mpy     x0,y1,a
        tfr     a,b
        add     x1,a
        add     a,b
        move    a,x1                            ; low
        move    y0,a
        sub     x1,a b,x:(r4)+                  ; h; sm
        move    x:(r4)+,x0
        cmp     x0,a
        tgt     x0,a
        move    x:(r4)+,x0
        cmp     x0,a
        tlt     x0,a
        move    x:(r4)+,y1                      ; K (fills the tlt's wait)
        move    a,x0
        mpy     x0,y1,b
        asl     #4,b,b
        move    b,y0                            ; f (y is in x1 + h now; y1 y1 is not a multiplier pair)
        mpy     y0,y0,b
        move    b,y1
        mac     -x0,y1,a
        add     x1,a                            ; y
; ---- FM's source: y's one-pole high-pass at 5 Hz, held from the 4th samples (3, 7, 11, 15) to the next ones
        move    x:(r4)+,y1                      ; Gf5
        move    x:(r4),x1 a,y0                  ; shp; y
        sub     x1,a
        move    a,x0
        mpy     x0,y1,a
        tfr     a,b
        add     x1,a
        add     a,b
        neg     a
        add     y0,a b,x:(r4)+                  ; the high-pass; shp
        move    x:(r4),b                        ; W: its top bit (in b: the add's wait is filled; the asl's N and V are a's)
        move    a,x0                            ; the high-pass
        asl     #1,b,b
        move    b1,x:(r4)+
        move    x:(r4),a
        tlt     x0,a                            ; on a 4th sample, Yh = the high-pass
        move    a,x:(r4)+
        move    y0,a                            ; y, for DRIV (and in y0)
; ---- DRIV: x = y G; above the knee the mixer's soft ceiling, K + W tanh((|x| - K) / W) from the table -----------
        move    x:(r4)+,b                       ; DRIV's word; r4 on the level's step
        move    #$10,x0                         ; $100000 = DRIV 0 (the short form: bits 23..16)
        cmp     x0,b
        beq     o3v_koff                        ; DRIV 0: nothing
        move    b,y1
        mpy     y1,y0,a
        asl     #3,a,a                          ; x = y G
        move    #>818505,y0                      ; (fills the asl's wait)
        move    a,x1                            ; x, limited: its sign and its size
        move    x1,a
        abs     a
        move    #>$cc2,y1                     ; the + side's table, its place in Y (r1 is past lp2: free until the loop's end)
        move    x1,b
        tst     b
        bge     o3v_kside
        move    #>454725,y0
        move    #>$cda,y1
o3v_kside:
        sub     y0,a                            ; |x| - K
        move    #0,x0
        tst     a
        tlt     x0,a                            ; under the knee: the table's first point, K (and |x| is the smaller)
        move    #>180224,x0
        cmp     x0,a
        tgt     x0,a                            ; past the table's end: the end
        move    a,y0
        asr     #13,a,a
        add     y1,a
        move    y0,b                            ; (b, for the fraction: fills the add's wait)
        move    a1,r1                           ; T0's place in Y
        and     #>$1fff,b
        asl     #10,b,b
        move    y:(r1)+,y0                      ; T0 (fills the asl's wait)
        move    b,x0                            ; the fraction, 23 bits
        move    y:(r1),y1                       ; T1
        move    y0,a
        mac     x0,y1,a
        mac     -y0,x0,a                        ; the curve T0 + f (T1 - T0), exactly: never above |x| past the knee, K under it
        move    x1,b                            ; (fills the mac's wait)
        move    a,x0
        move    x1,a
        abs     a
        cmp     x0,a
        tgt     x0,a                            ; the smaller of |x| and the curve (no branch: the cycle count's rule)
        tst     b
        bge     o3v_koff
        neg     a
o3v_koff:
        move    a,x0                            ; y
        move    x:(r4)+,y0                      ; the output's level += its step
        move    x:(r4),b
        add     y0,b
        move    b,x:(r4)-
        move    b,y1
        move    (r4)-
        move    (r4)-                           ; (r4 back on Yh)
        mpy     x0,y1,a
        asl     #3,a,a
        move    r7,r1
        move    a,x:(r0)+                       ; L = R = the voice (the same limiting as through x0)
        move    a,x:(r0)+
        move    r3,r5
o3v_end:
o3v_pass:
        rts
; ---- no signature in this piece's record.  A first piece leaves the audio as it came and says so (2); a later piece
;      does the same only after such a first piece: after a taken or a refused one the records disagree, and what is
;      in the block is the engine's (payloads in R): silence.
o3v_uns:
        move    r0,b
        move    #>0,x0
        cmp     x0,b
        bne     o3v_ulat
        move    #>2,x0
        move    x0,x:(r7+$14)
        rts
o3v_ulat:
        move    x:(r7+$14),b
        move    #>2,x0
        clr     a
        cmp     x0,b
        bne     o3v_mz
        rts
o3v_bad:
        lua     (r7+7),r2
        clr     a
        do      #4,o3v_gz                       ; the gain and its step: the voice ramps in from 0 afterwards
        move    a,x:(r2)+
o3v_gz:
        move    a,x:(r7+$14)                    ; 0 = refused, for the frame's later pieces
o3v_mz:
        do      n7,o3v_mute                     ; this call's samples, no word more
        move    a,x:(r0)+
        move    a,x:(r0)+
o3v_mute:
        rts
